// modTagList["if you have a (%a+) (%a+) in (%a+) slot"] (ModParser.lua:1595)
fn f0106(c: &Ctx, a: &[Value]) -> Vec<Value> {
    let mut l__ = arg(a, 0);
    let mut l_rarity = arg(a, 1);
    let mut l_item = arg(a, 2);
    let mut l_slot = arg(a, 3);
    return vec![tbl(
        vec![(
            sb(b"tag"),
            tbl(
                vec![
                    (sb(b"type"), sb(b"Condition")),
                    (
                        sb(b"var"),
                        concat(
                            &first(gsub_fn(
                                &l_rarity.clone(),
                                &sb(b"^%l"),
                                &mut upper_fn,
                                &nil(),
                            )),
                            &concat(
                                &sb(b"ItemIn"),
                                &concat(
                                    &first(gsub_fn(
                                        &l_item.clone(),
                                        &sb(b"^%l"),
                                        &mut upper_fn,
                                        &nil(),
                                    )),
                                    &concat(&sb(b" "), &{
                                        let v = {
                                            let v = Value::Bool(eq(&l_slot.clone(), &sb(b"right")));
                                            if v.truthy() { n(2.0) } else { v }
                                        };
                                        if v.truthy() {
                                            v
                                        } else {
                                            {
                                                let v =
                                                    Value::Bool(eq(&l_slot.clone(), &sb(b"left")));
                                                if v.truthy() { n(1.0) } else { v }
                                            }
                                        }
                                    }),
                                ),
                            ),
                        ),
                    ),
                ],
                vec![],
            ),
        )],
        vec![],
    )];
}

