// specialModList["base (%a+) duration is ([%d%.]+) seconds?"] (ModParser.lua:3667)
fn f0550(c: &Ctx, a: &[Value]) -> Vec<Value> {
    let mut l__ = arg(a, 0);
    let mut l_ailment = arg(a, 1);
    let mut l_num = arg(a, 2);
    let mut l_ailmentName = {
        let v = {
            let v = {
                let v = Value::Bool(eq(&l_ailment.clone(), &sb(b"bleeding")));
                if v.truthy() {
                    v
                } else {
                    Value::Bool(eq(&l_ailment.clone(), &sb(b"bleed")))
                }
            };
            if v.truthy() { sb(b"Bleed") } else { v }
        };
        if v.truthy() {
            v
        } else {
            {
                let v = {
                    let v = Value::Bool(eq(&l_ailment.clone(), &sb(b"ignite")));
                    if v.truthy() {
                        v
                    } else {
                        Value::Bool(eq(&l_ailment.clone(), &sb(b"poison")))
                    }
                };
                if v.truthy() {
                    first(c.first_to_upper(vec![l_ailment.clone()]))
                } else {
                    v
                }
            }
        }
    };
    if (l_ailmentName.clone()).truthy() {
        return vec![tbl(vec![], {
            let mut v = vec![];
            v.extend(c.mod_({
                let mut v = vec![
                    concat(&l_ailmentName.clone(), &sb(b"DurationBase")),
                    sb(b"OVERRIDE"),
                ];
                v.extend(vec![tonumber(&l_num.clone())]);
                v
            }));
            v
        })];
    }
    vec![]
}

